//! Required Option disabled boolean reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><select id=select><option id=option selected=legacy value=one>One</option><option value=two>Two</option></select><datalist id=choices><option id=suggestion>Suggestion</option></datalist><input id=neighbor value=seed></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://option-default-selected.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn option_default_selected_canonical_boolean_accessor_and_actual_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),P=HTMLOptionElement.prototype,a=Object.getOwnPropertyDescriptor(P,'defaultSelected');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get defaultSelected'||a.set.name!=='set defaultSelected'||Object.hasOwn(x,'defaultSelected')||x.defaultSelected!==true||x.getAttribute('selected')!=='legacy'||document.createElement('option').defaultSelected!==false)throw 'canonical disabled boolean';"#);}
#[test]
fn option_default_selected_native_boolean_conversion_identity_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),old=x.getAttributeNode('selected'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.defaultSelected=false;var records=watch.takeRecords();if(x.defaultSelected!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='selected')throw 'false removes actual attribute';var calls=0;x.defaultSelected={toString:function(){calls++;return '';},valueOf:function(){calls++;return 0;}};var attr=x.getAttributeNode('selected');records=watch.takeRecords();if(calls||x.defaultSelected!==true||attr===null||attr.value!==''||records.length!==1||records[0].oldValue!==null||document.getElementById('neighbor').value!=='seed')throw 'boolean conversion keeps actual record';x.defaultSelected='';if(x.defaultSelected!==false||attr.ownerElement!==null)throw 'empty string is false';"#);}

#[test]
fn option_default_selected_updates_native_selection_until_dirty_and_reset_uses_current_defaults(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),s=document.getElementById('select'),y=s.lastChild; y.defaultSelected=true;if(s.selectedIndex!==1||s.value!=='two'||!y.hasAttribute('selected'))throw 'new default selects';s.selectedIndex=0;x.defaultSelected=false;if(s.selectedIndex!==0||x.hasAttribute('selected'))throw 'dirty option remains selected';y.defaultSelected=false;if(s.selectedIndex!==0)throw 'unselected default removal';");}
#[test]
fn option_default_selected_inert_exact_namespace_and_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','p:option');x.setAttributeNS('urn:foreign','selected','yes');x.setAttributeNS(null,'SELECTED','yes');if(x.defaultSelected!==false)throw 'exact presence';x.defaultSelected=true;var attr=x.getAttributeNodeNS(null,'selected');if(!x.defaultSelected||attr.value!=='')throw 'real inert selected';x.defaultSelected=false;if(x.defaultSelected||attr.ownerElement!==null)throw 'real inert removal';");}

#[test]
fn option_default_selected_brand_precedes_hooks_and_keeps_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('option'),C=HTMLOptionElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'defaultSelected'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('ul'),document.createElement('li'),document.createElement('dl'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','option'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OL')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'disabled getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return '';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'disabled setter brand';}Object.defineProperty(x,'defaultSelected',{value:'author',writable:true,configurable:true});a.set.call(x,false);if(x.defaultSelected!=='author'||x.hasAttribute('selected'))throw 'canonical attribute authority';delete x.defaultSelected;if(x.defaultSelected!==false||Object.hasOwn(x,'defaultSelected'))throw 'restored inherited boolean';delete window.HTMLOptionElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved canonical interface';"#);}
#[test]
fn option_default_selected_raw_attribute_aliases_observe_presence_and_preserve_exact_backing(){let(mut d,mut f,mut p)=fixture();for inert in [false,true]{run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');x.defaultSelected=true;"}else{"var x=document.getElementById('option');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('selected'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','nodeValue','textContent']){a[key]='R\ud800'+key;if(x.defaultSelected!==true||a.value!=='R\ud800'+key||x.getAttributeNode('selected')!==a)throw 'raw boolean backing';}var old=a.value;x.defaultSelected=true;var records=watch.takeRecords();if(x.defaultSelected!==true||a.value!==''||records.length!==4||records[3].oldValue!==old||x.getAttributeNode('selected')!==a)throw 'boolean normalization uses current Attr';x.removeAttribute('selected');if(x.defaultSelected!==false||a.ownerElement!==null)throw 'actual boolean removal';x.setAttributeNS('urn:foreign','selected','foreign');x.setAttributeNS(null,'SELECTED','upper');if(x.defaultSelected!==false)throw 'exact disabled authority';x.setAttributeNS(null,'selected','A\udfffZ');if(x.ownerDocument!==document){var clone=x.cloneNode(false);if(!x.defaultSelected||!clone.defaultSelected||clone.getAttributeNodeNS(null,'selected').value!=='A\udfffZ'||clone.getAttributeNodeNS(null,'selected')===x.getAttributeNodeNS(null,'selected'))throw 'raw presence copy';}"#);}}
#[test]
fn option_default_selected_saved_child_origin_refuses_before_observation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLOptionElement.prototype,'defaultSelected');a.set.call(x,false);if(a.get.call(x)!==false)throw 'same origin boolean';");p.set_location(&crate::navigation::address("https://other-disabled.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,true);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://option-default-selected.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(x.defaultSelected!==false)throw 'origin refusal preserves value';a.set.call(x,true);if(!a.get.call(x)||x.getAttribute('selected')!=='')throw 'saved boolean recovery';");}


#[test]
fn option_default_selected_writer_refusal_preserves_native_state_records_and_recovers(){for inert in [false,true]{for mode in 0..(if inert{4}else{5}){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','option');"}else{"var x=document.getElementById('select').lastChild;"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let native=format!("{:?}",f.controls.values().map(|c|(&c.select,&c.caption,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset)).collect::<Vec<_>>());let retained=p.state.retained;let commits=p.state.dom_commits;let limit=p.state.retained_limit;let entry=p.state.limits.test_entry_arenas;let attrs=p.state.limits.host.element_attributes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=retained,3=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.limits.test_entry_arenas=true;p.state.limits.host.element_attributes=0;}}let e=p.runtime.execute("x.defaultSelected=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).err().unwrap_or_else(||panic!("expected refusal inert={inert} mode={mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}:{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(format!("{:?}",f.controls.values().map(|c|(&c.select,&c.caption,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset)).collect::<Vec<_>>()),native);assert_eq!((p.state.retained,p.state.dom_commits),(retained,commits));p.state.retained_limit=limit;p.state.execution_deadline=None;p.state.limits.test_entry_arenas=entry;p.state.limits.host.element_attributes=attrs;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.defaultSelected!==false||watch.takeRecords().length)throw 'atomic refusal';x.defaultSelected=true;var records=watch.takeRecords();if(!x.defaultSelected||records.length!==1||records[0].attributeName!=='selected'||records[0].oldValue!==null)throw 'fresh recovery';");}}}
#[test]
fn option_default_selected_native_exact_attribute_producers_and_last_default_reset(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r"var s=document.getElementById('select'),x=document.getElementById('option'),y=s.lastChild;x.setAttributeNS('urn:foreign','selected','foreign');x.setAttributeNS(null,'SELECTED','upper');y.setAttribute('selected','A\ud800Z');var attr=y.getAttributeNode('selected');if(!y.defaultSelected||s.value!=='two'||attr.value!=='A\ud800Z')throw 'actual raw selected producer';attr.value='Changed';if(s.value!=='two'||!y.defaultSelected)throw 'present attr stays present';s.selectedIndex=0;y.removeAttributeNode(attr);if(y.defaultSelected||s.value!=='one'||attr.ownerElement!==null)throw 'remove unselected default';y.defaultSelected=true;if(s.value!=='two')throw 'clean option default selects';");let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();assert_eq!(f.controls[&select].caption,"Two");assert_eq!(f.controls[&select].value.text(),"two");}
#[test]
fn option_default_selected_script_value_and_pointer_dirtiness_keep_current_selection(){for source in ["document.getElementById('select').value='one';","document.getElementById('select').selectedIndex=0;"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var x=document.getElementById('option'),s=document.getElementById('select');x.defaultSelected=false;if(s.selectedIndex!==0||s.value!=='one')throw 'dirty chosen option remains selected';x.defaultSelected=true;if(s.selectedIndex!==0)throw 'dirty default add';");}let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();assert!(!f.select_option(select,0).unwrap());run(&mut d,&mut f,&mut p,"var x=document.getElementById('option');x.defaultSelected=false;if(document.getElementById('select').value!=='one')throw 'native same selection dirties';");assert!(f.controls[&select].select.as_ref().unwrap().options[0].dirty_selected);}
#[test]
fn option_default_selected_native_reset_uses_current_defaults_and_clears_dirtiness(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var s=document.getElementById('select'),x=document.getElementById('option'),y=s.lastChild;s.value='two';y.defaultSelected=true;x.defaultSelected=false;");let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();f.reset_in_document(&d,owner).unwrap();assert_eq!(f.controls[&select].value.text(),"two");assert!(f.controls[&select].select.as_ref().unwrap().options.iter().all(|o|!o.dirty_selected));run(&mut d,&mut f,&mut p,"y.defaultSelected=false;if(s.value!=='one'||s.selectedIndex!==0)throw 'reset clean fallback';x.defaultSelected=true;s.value='two';");f.reset_in_document(&d,owner).unwrap();assert_eq!(f.controls[&select].value.text(),"one");}
#[test]
fn option_default_selected_same_presence_preserves_native_editor_and_namespace_aliases(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let c=f.controls.get_mut(&select).unwrap();c.value.cursor=2;c.value.anchor=1;c.value.offset=1;run(&mut d,&mut f,&mut p,"var x=document.getElementById('option');x.defaultSelected=true;x.setAttributeNS('urn:foreign','selected','a');x.setAttributeNS(null,'SELECTED','b');if(!x.defaultSelected)throw 'actual lower selected remains';");let e=&f.controls[&select].value;assert_eq!((e.cursor,e.anchor,e.offset),(2,1,1));}
#[test]
fn option_default_selected_native_combined_payload_refusal_recovers(){let mut source=String::from("<form id=form><select id=select><option id=option selected value=one>One</option><option value=two>Two</option></select>");for n in 0..16{source.push_str(&format!("<input id=neighbor{n} value=seed>"));}source.push_str("</form>");let mut d=crate::html::parse(&source);d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select').lastChild;x.value='Longer chosen value';");let base=f.controls.values().map(|c|c.name.len()+c.value.text().len()+c.select.as_ref().map_or(0,|s|s.options.iter().map(|o|o.value.len()+o.label.len()).sum::<usize>())).sum::<usize>();let mut remaining=128*1024-base-10;for c in f.controls.values_mut().filter(|c|c.kind==forms::Kind::Text){let n=remaining.min(8192);c.name="n".repeat(n);remaining-=n;}assert_eq!(remaining,0);let before=format!("{:?}",d.nodes);let native=format!("{:?}",f.controls[&select].select);let error=p.runtime.execute("x.defaultSelected=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state});let error=error.unwrap_err();assert!(error.contains("128 KiB"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(format!("{:?}",f.controls[&select].select),native);for c in f.controls.values_mut().filter(|c|c.kind==forms::Kind::Text){c.name.clear();}p.begin_job();run(&mut d,&mut f,&mut p,"x.defaultSelected=true;if(document.getElementById('select').value!=='Longer chosen value')throw 'native payload recovery';");}
